mapper.select:
SELECT
    id, bot_id, bot_name, user_id, account_id, exchange, strategy_id,
    trading_pair, allocated_capital, current_capital, status,
    start_time, last_signal_time, created_at, updated_at,
    created_by, updated_by, configuration, statistics,
    enabled, remark
FROM trading_bot


        AND bot_name LIKE CONCAT('%', #{botName}, '%')


        AND user_id = #{userId}


        AND exchange = #{exchange}


        AND trading_pair = #{tradingPair}


        AND status = #{status}


        AND strategy_id = #{strategyId}


        AND account_id = #{accountId}


ORDER BY created_at DESC

mapper.update:
UPDATE trading_bot
SET status = #{status}, updated_at = NOW()
WHERE bot_id = #{botId}

UPDATE trading_bot
SET statistics = #{statistics}, updated_at = NOW()
WHERE bot_id = #{botId}
